/*:
 * @target MZ
 * @plugindesc A dynamic treasure generation system with rarity, gold generation, and respawn features. Inspired by NWN loot system module.
 * @author Dark_Ansem
 *
 * @param TreasureData
 * @type struct<TreasureContainer>[]
 * @default []
 * @desc Define the treasure containers with loot based on rarity.
 *
 * @param RespawnDelay
 * @type number
 * @default 300
 * @desc Default respawn delay in seconds for containers.
 */

/*~struct~TreasureContainer:
 * @param Tag
 * @type string
 * @desc The tag identifying this container.
 *
 * @param Common
 * @type item[]
 * @default []
 * @desc Items for common loot.
 *
 * @param Rare
 * @type item[]
 * @default []
 * @desc Items for rare loot.
 *
 * @param Exceptional
 * @type item[]
 * @default []
 * @desc Items for exceptional loot.
 */

(() => {
    const pluginName = "TreasureSystem";
    const params = PluginManager.parameters(pluginName);
    const treasureData = JSON.parse(params["TreasureData"] || "[]").map(container => ({
        ...container,
        Common: container.Common ? JSON.parse(container.Common) : [],
        Rare: container.Rare ? JSON.parse(container.Rare) : [],
        Exceptional: container.Exceptional ? JSON.parse(container.Exceptional) : []
    }));
    const defaultRespawnDelay = parseInt(params["RespawnDelay"], 10) || 300;

    // Utility function for rolling dice
    const rollDice = (sides) => Math.floor(Math.random() * sides) + 1;

    // Fetch treasure based on tag and rarity
    const getTreasure = (containerTag, rarity) => {
        try {
            const container = treasureData.find(c => c.Tag === containerTag);
            if (!container) {
                console.error(`Treasure container "${containerTag}" not found.`);
                return null;
            }

            const items = container[rarity];
            if (!items || items.length === 0) {
                console.warn(`No items found for rarity "${rarity}" in container "${containerTag}".`);
                return null;
            }

            return items[Math.floor(Math.random() * items.length)];
        } catch (e) {
            console.error(`Error fetching treasure for tag "${containerTag}" and rarity "${rarity}": ${e.message}`);
            return null;
        }
    };

    // Respawn containers with RPG Maker timing system
    Game_Map.prototype.respawnContainer = function(eventId, mapId, eventData, delay = defaultRespawnDelay) {
        const timer = setTimeout(() => {
            if ($gameMap.mapId() === mapId) {
                this.addEventAtLocation(eventData, eventId);
            }
        }, delay * 1000);

        // Store timer reference for cleanup
        this._respawnTimers = this._respawnTimers || new Map();
        this._respawnTimers.set(eventId, timer);
    };

    // Add event at a specific location
    Game_Map.prototype.addEventAtLocation = function(eventData, eventId) {
        const { x, y } = eventData;
        $dataMap.events[eventId] = eventData;
        const newEvent = new Game_Event($gameMap.mapId(), eventId);
        $gameMap._events[eventId] = newEvent;
        $gameMap.refreshTileEvents();
        $gamePlayer.refresh();
    };

    // Clear all respawn timers
    Game_Map.prototype.clearRespawnTimers = function() {
        if (this._respawnTimers) {
            for (const [eventId, timer] of this._respawnTimers) {
                clearTimeout(timer);
            }
            this._respawnTimers.clear();
        }
    };

    // Cleanup during map transitions
    const alias_Game_Map_terminate = Game_Map.prototype.terminate;
    Game_Map.prototype.terminate = function() {
        this.clearRespawnTimers();
        alias_Game_Map_terminate.call(this);
    };

    // Extend event functionality for treasure logic
    Game_Event.prototype.onOpen = function() {
        if (this.getSelfSwitch("Used")) return;

        this.setSelfSwitch("Used", true);
        const player = $gameParty.members()[0];
        const chestGold = parseFloat(this.event().meta.GoldMultiplier || 1.0);
        const chestTag = this.event().meta.TreasureTag || "Default";

        // Generate Gold
        const goldAmount = Math.floor(player.level * rollDice(20) * chestGold);
        $gameParty.gainGold(goldAmount);
        $gameMessage.add(`You found ${goldAmount} gold!`);

        // Generate Treasure
        const rollNumber = rollDice(20);
        this.makeTreasure(chestTag, "Common");
        if (rollNumber >= 12) this.makeTreasure(chestTag, "Rare");
        if (rollNumber >= 18) this.makeTreasure(chestTag, "Exceptional");
    };

    Game_Event.prototype.makeTreasure = function(containerTag, rarity) {
        const treasure = getTreasure(containerTag, rarity);
        if (treasure) {
            $gameParty.gainItem($dataItems[parseInt(treasure)], 1);
            $gameMessage.add(`You found a ${rarity} item!`);
        }
    };

    Game_Event.prototype.onClose = function() {
        const respawnDelay = parseInt(this.event().meta.RespawnDelay || defaultRespawnDelay, 10);
        this.clearInventory();
        this.respawnContainer(respawnDelay);
    };

    Game_Event.prototype.clearInventory = function() {
        console.log("Inventory cleared.");
    };

    Game_Event.prototype.getSelfSwitch = function(switchKey) {
        return $gameSelfSwitches.value([$gameMap.mapId(), this.eventId(), switchKey]);
    };

    Game_Event.prototype.setSelfSwitch = function(switchKey, value) {
        $gameSelfSwitches.setValue([$gameMap.mapId(), this.eventId(), switchKey], value);
    };

    // Event triggers
    const alias_Game_Event_start = Game_Event.prototype.start;
    Game_Event.prototype.start = function() {
        if (this.event().meta.TreasureTag) {
            this.onOpen();
        } else {
            alias_Game_Event_start.call(this);
        }
    };

    const alias_Game_Event_erase = Game_Event.prototype.erase;
    Game_Event.prototype.erase = function() {
        if (this.event().meta.TreasureTag) {
            this.onClose();
        } else {
            alias_Game_Event_erase.call(this);
        }
    };
})();
